  'indicateurs.comprendre.delai_prise_charge_temps': '<b>Yanıt süresi</b>: talep (veya iş emrinin oluşturulması) ile müdahalenin başlaması arasındaki süre; önceliğe göre medyan ve hedef süre içinde üstlenilen iş emirlerinin payı.',
